package br.com.burstlab.common;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.stereotype.Component;
import java.net.URI;
import java.net.http.*;
import java.time.Duration;
@Component
public class BClient {
 public record Result(int status,String body,boolean certain) {}
 private final ObjectMapper json; private final HttpClient http=HttpClient.newBuilder().connectTimeout(Duration.ofMillis(300)).build();
 public BClient(ObjectMapper json){this.json=json;}
 public Result lookup(String key){
  try{var request=HttpRequest.newBuilder(URI.create(Settings.env("SERVICE_B_URL","http://localhost:8081")+"/api/results/"+key)).timeout(Duration.ofMillis(500)).GET().build();var r=http.send(request,HttpResponse.BodyHandlers.ofString());return new Result(r.statusCode(),r.body(),true);}
  catch(InterruptedException e){Thread.currentThread().interrupt();return new Result(503,"consulta interrompida",false);}
  catch(Exception e){return new Result(503,"resultado durável não pôde ser consultado",false);}
 }
 public Result call(String key,String value,String correlation,long deadline){
  long remaining=deadline-System.currentTimeMillis();if(remaining<50)return new Result(504,"prazo esgotado antes de B",true);
  try{
   HttpRequest request=HttpRequest.newBuilder(URI.create(Settings.env("SERVICE_B_URL","http://localhost:8081")+"/api/work"))
    .timeout(Duration.ofMillis(Math.min(1000,remaining))).header("Content-Type","application/json")
    .header("Idempotency-Key",key).header("X-Correlation-Id",correlation).header("X-Deadline-Epoch-Ms",""+deadline)
    .POST(HttpRequest.BodyPublishers.ofString(json.writeValueAsString(new Payload(value)))).build();
   HttpResponse<String> response=http.send(request,HttpResponse.BodyHandlers.ofString());return new Result(response.statusCode(),response.body(),true);
  }catch(InterruptedException e){Thread.currentThread().interrupt();return new Result(503,"operação cancelada; resultado pode ser incerto",false);}
  catch(Exception e){return new Result(504,"timeout/falha de transporte; resultado de B incerto",false);}
 }
}

package br.com.burstlab.common;
import org.springframework.context.annotation.*;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import software.amazon.awssdk.services.sqs.SqsClient;
import software.amazon.awssdk.regions.Region;
import software.amazon.awssdk.auth.credentials.*;
import software.amazon.awssdk.http.urlconnection.UrlConnectionHttpClient;
import software.amazon.awssdk.core.client.config.ClientOverrideConfiguration;
import java.time.Duration;
import java.net.URI;
@Configuration
public class CommonConfiguration {
 @Bean(destroyMethod="close") @ConditionalOnProperty(name="burstlab.admission",havingValue="true",matchIfMissing=true)
 public RedisLimiter limiter(){return new RedisLimiter(Settings.env("REDIS_URI","redis://localhost:6379"),"service-b",Settings.integer("LIMITER_CAPACITY",8),Settings.integer("LIMITER_RATE",32),Settings.integer("LIMITER_CONCURRENCY",8),Settings.integer("LIMITER_LEASE_MS",5000));}
 @Bean(destroyMethod="close") @ConditionalOnProperty(name="burstlab.queue",havingValue="true",matchIfMissing=true)
 public SqsClient sqs(){var b=SqsClient.builder().region(Region.of(Settings.env("AWS_REGION","us-east-1"))).httpClientBuilder(UrlConnectionHttpClient.builder().connectionTimeout(Duration.ofSeconds(2)).socketTimeout(Duration.ofSeconds(25))).overrideConfiguration(ClientOverrideConfiguration.builder().apiCallTimeout(Duration.ofSeconds(28)).apiCallAttemptTimeout(Duration.ofSeconds(26)).build());
  String endpoint=System.getenv("SQS_ENDPOINT");if(endpoint!=null&&!endpoint.isBlank())b.endpointOverride(URI.create(endpoint)).credentialsProvider(StaticCredentialsProvider.create(AwsBasicCredentials.create("test","test")));
  return b.build();}
}

package br.com.burstlab.common;
import jakarta.servlet.*;
import jakarta.servlet.http.*;
import org.springframework.stereotype.Component;
import org.springframework.web.filter.OncePerRequestFilter;
import java.io.IOException;
import java.util.UUID;
@Component
public class CorrelationFilter extends OncePerRequestFilter {
 protected void doFilterInternal(HttpServletRequest request,HttpServletResponse response,FilterChain chain)throws ServletException,IOException {
  String c=request.getHeader("X-Correlation-Id");if(c==null||!c.matches("[A-Za-z0-9._:-]{1,128}"))c=UUID.randomUUID().toString();
  request.setAttribute("correlationId",c);response.setHeader("X-Correlation-Id",c);
  org.slf4j.MDC.put("correlationId",c);
  try{chain.doFilter(request,response);}finally{org.slf4j.MDC.remove("correlationId");}
 }
}

package br.com.burstlab.common;
import org.springframework.stereotype.Repository;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.http.HttpStatus;
import java.util.*;
@Repository
public class JobStore {
 public record Job(UUID id,String key,String value,String correlation,String status,int attempts,long deadline,String result,String error) {}
 private final JdbcTemplate db; private final TransactionTemplate tx;
 public JobStore(JdbcTemplate db,TransactionTemplate tx){this.db=db;this.tx=tx;}
 public Job get(UUID id){return db.query("SELECT * FROM jobs WHERE id=?",(r,n)->new Job(r.getObject("id",UUID.class),r.getString("request_key"),r.getString("payload"),r.getString("correlation"),r.getString("status"),r.getInt("attempts"),r.getTimestamp("deadline").getTime(),r.getString("result"),r.getString("error")),id).stream().findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"job inexistente"));}
 public Job accept(String key,String value,String correlation){return tx.execute(s->{
  UUID id=UUID.randomUUID();int inserted=db.update("INSERT INTO jobs(id,request_key,payload,correlation,deadline) VALUES (?,?,?,?,now()+interval '120 seconds') ON CONFLICT(request_key) DO NOTHING",id,key,value,correlation);
  if(inserted==1)db.update("INSERT INTO outbox(job_id,destination) VALUES (?,'MAIN')",id);
  UUID actual=db.queryForObject("SELECT id FROM jobs WHERE request_key=?",UUID.class,key);Job job=get(actual);
  if(!job.value.equals(value))throw new ResponseStatusException(HttpStatus.CONFLICT,"mesma chave com payload diferente");return job;
 });}
 public boolean claim(UUID id,UUID owner){return db.update("UPDATE jobs SET status='PROCESSING',owner=?,locked_until=now()+interval '35 seconds' WHERE id=? AND status IN ('QUEUED','PROCESSING') AND (locked_until IS NULL OR locked_until<now()) AND next_attempt<=now()",owner,id)==1;}
 public int beginAttempt(UUID id,UUID owner){return db.queryForObject("UPDATE jobs SET attempts=attempts+1 WHERE id=? AND owner=? AND attempts<3 RETURNING attempts",Integer.class,id,owner);}
 public void delay(UUID id,UUID owner,int seconds,String error){db.update("UPDATE jobs SET status='QUEUED',owner=NULL,locked_until=NULL,next_attempt=now()+(? * interval '1 second'),error=? WHERE id=? AND owner=?",seconds,error,id,owner);}
 public void success(UUID id,UUID owner,String result){int n=db.update("UPDATE jobs SET status='SUCCEEDED',result=?,owner=NULL,locked_until=NULL,error=NULL WHERE id=? AND owner=?",result,id,owner);if(n!=1)throw new IllegalStateException("claim perdido");}
 public void fail(UUID id,UUID owner,String status,String error){tx.executeWithoutResult(s->{int n=db.update("UPDATE jobs SET status=?,error=?,owner=NULL,locked_until=NULL WHERE id=? AND owner=?",status,error,id,owner);if(n==1)db.update("INSERT INTO outbox(job_id,destination) VALUES (?,'DLQ') ON CONFLICT DO NOTHING",id);});}
 public boolean terminal(Job job){return Set.of("SUCCEEDED","FAILED","EXPIRED","RESULT_UNKNOWN").contains(job.status);}
}

package br.com.burstlab.common;
import org.springframework.stereotype.Component;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.support.TransactionTemplate;
import software.amazon.awssdk.services.sqs.SqsClient;
import org.slf4j.LoggerFactory;
@Component @ConditionalOnProperty(name="burstlab.queue",havingValue="true",matchIfMissing=true)
public class OutboxPublisher {
 private final JdbcTemplate db;private final TransactionTemplate tx;private final SqsClient sqs;
 public OutboxPublisher(JdbcTemplate db,TransactionTemplate tx,SqsClient sqs){this.db=db;this.tx=tx;this.sqs=sqs;}
 @Scheduled(fixedDelay=100)
 public void publish(){try{for(int i=0;i<20;i++){Boolean sent=tx.execute(status->{var rows=db.queryForList("SELECT id,job_id,destination FROM outbox WHERE published_at IS NULL ORDER BY id FOR UPDATE SKIP LOCKED LIMIT 1");if(rows.isEmpty())return false;var row=rows.get(0);
   String url=Settings.env(row.get("destination").equals("DLQ")?"SQS_DLQ_URL":"SQS_QUEUE_URL","");
   if(url.isBlank())throw new IllegalStateException("URL SQS obrigatória");
   sqs.sendMessage(b->b.queueUrl(url).messageBody(row.get("job_id").toString()));
   db.update("UPDATE outbox SET published_at=now() WHERE id=?",row.get("id"));return true;});if(!Boolean.TRUE.equals(sent))break;}}
  catch(Exception e){LoggerFactory.getLogger(getClass()).warn("outbox pendente; recuperação automática: {}",e.getClass().getSimpleName());}}
}

package br.com.burstlab.common;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.http.HttpStatus;
public record Payload(String value) {
 public Payload { if(value==null||value.isBlank()||value.length()>1000)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"value deve conter de 1 a 1000 caracteres"); }
 public static String key(String key){if(key!=null&&key.length()>120)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"chave externa deve ter até 120 caracteres");return operationKey(key);}
 public static String operationKey(String key){if(key==null||!key.matches("[A-Za-z0-9._:-]{1,128}"))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Idempotency-Key inválido (1–128 caracteres seguros)");return key;}
}

package br.com.burstlab.common;
import io.lettuce.core.*;
import io.lettuce.core.api.StatefulRedisConnection;
import io.lettuce.core.resource.DefaultClientResources;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.time.Duration;
import java.util.*;
public final class RedisLimiter implements AutoCloseable {
 public record Admission(boolean allowed,double remainingTokens,long retryAfterMs,String reason,String leaseId) {}
 private final RedisClient client; private final StatefulRedisConnection<String,String> connection;
 private final DefaultClientResources resources; private final String script; private volatile String sha;
 private final String bucket,leases; private final double capacity,rate; private final int concurrency,leaseMs;
 public RedisLimiter(String uri,String group,double capacity,double rate,int concurrency,int leaseMs) {
  this.capacity=capacity;this.rate=rate;this.concurrency=concurrency;this.leaseMs=leaseMs;
  bucket="burstlab:{"+group+"}:bucket:v1";leases="burstlab:{"+group+"}:leases:v1";
  resources=DefaultClientResources.builder().ioThreadPoolSize(2).computationThreadPoolSize(2).build();
  RedisURI redisUri=RedisURI.create(uri);redisUri.setTimeout(Duration.ofMillis(100));
  client=RedisClient.create(resources,redisUri);
  client.setOptions(ClientOptions.builder().disconnectedBehavior(ClientOptions.DisconnectedBehavior.REJECT_COMMANDS).requestQueueSize(256).socketOptions(SocketOptions.builder().connectTimeout(Duration.ofMillis(300)).build()).timeoutOptions(TimeoutOptions.enabled(Duration.ofMillis(100))).build());
  connection=client.connect();
  try(var stream=getClass().getResourceAsStream("/lua/admit-v1.lua")){script=new String(Objects.requireNonNull(stream).readAllBytes(),StandardCharsets.UTF_8);}catch(IOException e){throw new IllegalStateException(e);}
  sha=connection.sync().scriptLoad(script);
 }
 public Admission acquire(){return acquire(1);}
 public Admission acquire(double cost){
  String id=UUID.randomUUID().toString(); List<Object> result;
  String[] keys={bucket,leases};String[] args={""+capacity,""+rate,""+cost,""+concurrency,""+leaseMs,id};
  try{result=connection.sync().evalsha(sha,ScriptOutputType.MULTI,keys,args);}
  catch(RedisNoScriptException e){sha=connection.sync().scriptLoad(script);result=connection.sync().evalsha(sha,ScriptOutputType.MULTI,keys,args);}
  return new Admission(((Number)result.get(0)).longValue()==1,Double.parseDouble(result.get(1).toString()),((Number)result.get(2)).longValue(),result.get(3).toString(),id);
 }
 public void release(Admission admission){if(admission.allowed())connection.sync().zrem(leases,admission.leaseId());}
 public void close(){connection.close();client.shutdown();resources.shutdown();}
}

package br.com.burstlab.common;
import jakarta.annotation.PostConstruct;
import javax.sql.DataSource;
import org.springframework.stereotype.Component;
import org.springframework.core.io.ClassPathResource;
import org.springframework.jdbc.datasource.init.ScriptUtils;
@Component
public class SchemaInitializer {
 private final DataSource dataSource;
 public SchemaInitializer(DataSource dataSource){this.dataSource=dataSource;}
 @PostConstruct public void initialize()throws Exception {
  try(var connection=dataSource.getConnection();var statement=connection.createStatement()){
   statement.execute("SELECT pg_advisory_lock(108844)");
   try{ScriptUtils.executeSqlScript(connection,new ClassPathResource("schema.sql"));}
   finally{statement.execute("SELECT pg_advisory_unlock(108844)");}
  }
 }
}

package br.com.burstlab.common;
public final class Settings {
 private Settings() {}
 public static String env(String name,String fallback){String v=System.getenv(name);return v==null||v.isBlank()?fallback:v;}
 public static int integer(String name,int fallback){return Integer.parseInt(env(name,""+fallback));}
 public static boolean flag(String name){return Boolean.parseBoolean(env(name,"false"));}
}

CREATE TABLE IF NOT EXISTS jobs (
 id UUID PRIMARY KEY, request_key VARCHAR(128) NOT NULL UNIQUE, payload TEXT NOT NULL,
 correlation VARCHAR(128) NOT NULL, status VARCHAR(24) NOT NULL DEFAULT 'QUEUED',
 created_at TIMESTAMPTZ NOT NULL DEFAULT now(), deadline TIMESTAMPTZ NOT NULL,
 attempts INT NOT NULL DEFAULT 0, owner UUID, locked_until TIMESTAMPTZ,
 next_attempt TIMESTAMPTZ NOT NULL DEFAULT now(), result TEXT, error TEXT
);
CREATE TABLE IF NOT EXISTS outbox (
 id BIGSERIAL PRIMARY KEY, job_id UUID NOT NULL REFERENCES jobs(id), destination VARCHAR(8) NOT NULL,
 published_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(job_id,destination)
);
CREATE INDEX IF NOT EXISTS outbox_pending ON outbox(id) WHERE published_at IS NULL;
CREATE TABLE IF NOT EXISTS b_effects (
 operation_id VARCHAR(128) PRIMARY KEY, payload TEXT NOT NULL, result TEXT NOT NULL,
 applied_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

package br.com.burstlab.common;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class PayloadTest {
 @Test void boundedPayloadAndSafeKeys(){assertEquals("pedido",new Payload("pedido").value());assertThrows(RuntimeException.class,()->new Payload(""));assertThrows(RuntimeException.class,()->new Payload("a".repeat(1001)));assertThrows(RuntimeException.class,()->Payload.key("a\nInjected: true"));assertThrows(RuntimeException.class,()->Payload.key("a".repeat(129)));}
}

package br.com.burstlab.common;
import org.junit.jupiter.api.*;
import org.testcontainers.containers.GenericContainer;
import org.testcontainers.junit.jupiter.*;
import io.lettuce.core.RedisClient;
import java.util.*;
import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;
class RedisLimiterTest {
 static GenericContainer<?> redis;static String testUri;
 @BeforeAll static void start(){testUri=System.getenv("REDIS_TEST_URI");if(testUri==null){Assumptions.assumeTrue(org.testcontainers.DockerClientFactory.instance().isDockerAvailable(),"Docker indisponível; use REDIS_TEST_URI");redis=new GenericContainer<>("redis:7.2.7-alpine").withExposedPorts(6379);redis.start();testUri="redis://"+redis.getHost()+":"+redis.getMappedPort(6379);}}
 @AfterAll static void stop(){if(redis!=null)redis.stop();}
 String uri(){return testUri;}
 RedisLimiter create(String group,double c,double rate,int slots){return new RedisLimiter(uri(),group,c,rate,slots,5000);}
 String group(){return UUID.randomUUID().toString();}
 @Test void fullEmptyAndReleaseDoesNotRefund(){try(var l=create(group(),1,0.001,1)){var a=l.acquire();assertTrue(a.allowed());assertEquals(0,a.remainingTokens(),0.01);l.release(a);var denied=l.acquire();assertFalse(denied.allowed());assertEquals("TOKEN",denied.reason());assertTrue(denied.retryAfterMs()>0);}}
 @Test void partialRefillAndCeiling()throws Exception {try(var l=create(group(),4,2,20)){assertTrue(l.acquire(4).allowed());Thread.sleep(200);var a=l.acquire(0.25);assertTrue(a.allowed());assertTrue(a.remainingTokens()<1);Thread.sleep(2100);var b=l.acquire();assertTrue(b.allowed());assertTrue(b.remainingTokens()<=3.0001);}}
 @Test void invalidAndImpossibleCosts(){try(var l=create(group(),8,32,8)){for(double c:new double[]{0,-1,Double.NaN,Double.POSITIVE_INFINITY})assertThrows(RuntimeException.class,()->l.acquire(c));var a=l.acquire(9);assertFalse(a.allowed());assertEquals(-1,a.retryAfterMs());assertEquals("COST_EXCEEDS_CAPACITY",a.reason());}}
 @Test void invalidConfigurationRejected(){try(var l=create(group(),-1,32,8)){assertThrows(RuntimeException.class,l::acquire);}}
 @Test void expirationOnlyAfterFullRefill()throws Exception{String group=group();try(var l=create(group,1,10,8)){var a=l.acquire();l.release(a);Thread.sleep(1200);var client=RedisClient.create(uri());try(var c=client.connect()){assertEquals(0,c.sync().exists("burstlab:{"+group+"}:bucket:v1"));}finally{client.shutdown();}assertTrue(l.acquire().allowed());}}
 @Test void replicasShareAtomicGlobalBudget()throws Exception {String group=group();try(var one=create(group,8,0.0001,8);var two=create(group,8,0.0001,8)){var pool=Executors.newFixedThreadPool(8);try{List<Callable<Boolean>> calls=new ArrayList<>();for(int i=0;i<64;i++){var l=i%2==0?one:two;calls.add(()->l.acquire().allowed());}long allowed=0;for(var f:pool.invokeAll(calls))if(f.get())allowed++;assertEquals(8,allowed);}finally{pool.shutdownNow();}}}
 @Test void clockRollbackDoesNotPrematurelyExpireBucket(){String group=group();String key="burstlab:{"+group+"}:bucket:v1";try(var l=create(group,1,10,8)){var client=RedisClient.create(uri());try(var c=client.connect()){var time=c.sync().time();double now=Double.parseDouble(time.get(0))*1000+Double.parseDouble(time.get(1))/1000;c.sync().hset(key,Map.of("tokens","0","ts",""+(now+10000)));var a=l.acquire();assertFalse(a.allowed());assertTrue(a.retryAfterMs()>=10000);assertTrue(c.sync().pttl(key)>=10500,"TTL deve incluir relógio futuro + reposição");}finally{client.shutdown();}}}
 @Test void clockRollbackKeepsOlderFutureLeases(){String group=group();String key="burstlab:{"+group+"}:leases:v1";try(var l=create(group,8,32,8)){var client=RedisClient.create(uri());try(var c=client.connect()){var time=c.sync().time();double now=Double.parseDouble(time.get(0))*1000+Double.parseDouble(time.get(1))/1000;c.sync().zadd(key,now+20000,"old-lease");assertTrue(l.acquire().allowed());assertTrue(c.sync().pttl(key)>=20500,"TTL deve preservar lease antiga após retrocesso");}finally{client.shutdown();}}}
 @Test void noScriptRecovered(){try(var l=create(group(),8,32,8)){var client=RedisClient.create(uri());try(var c=client.connect()){c.sync().scriptFlush();}finally{client.shutdown();}assertTrue(l.acquire().allowed());}}
 @Test void configurationDriftRejected(){String group=group();try(var one=create(group,8,32,8);var two=create(group,8,33,8)){one.acquire();assertThrows(RuntimeException.class,two::acquire);}}
 @Test void demonstratesReadModifyWriteRace()throws Exception {var client=RedisClient.create(uri());try(var conn=client.connect()){String key="race:"+group();conn.sync().set(key,"1");var barrier=new CyclicBarrier(8);var pool=Executors.newFixedThreadPool(8);try{List<Callable<Boolean>> calls=new ArrayList<>();for(int i=0;i<8;i++)calls.add(()->{int previous=Integer.parseInt(conn.sync().get(key));barrier.await();if(previous>0){conn.sync().set(key,""+(previous-1));return true;}return false;});int allowed=0;for(var f:pool.invokeAll(calls))if(f.get())allowed++;assertEquals(8,allowed,"um token admitiu 8: corrida real");}finally{pool.shutdownNow();}}finally{client.shutdown();}}
}

resource "aws_appautoscaling_target" "worker" {
  count              = var.deploy_apps ? 1 : 0
  max_capacity       = 4
  min_capacity       = 1
  resource_id        = "service/${aws_ecs_cluster.lab.name}/${aws_ecs_service.app["worker"].name}"
  scalable_dimension = "ecs:service:DesiredCount"
  service_namespace  = "ecs"
}
resource "aws_appautoscaling_policy" "worker_up" {
  count              = var.deploy_apps ? 1 : 0
  name               = "${var.name}-worker-up"
  policy_type        = "StepScaling"
  resource_id        = aws_appautoscaling_target.worker[0].resource_id
  scalable_dimension = aws_appautoscaling_target.worker[0].scalable_dimension
  service_namespace  = "ecs"
  step_scaling_policy_configuration {
    adjustment_type         = "ChangeInCapacity"
    cooldown                = 60
    metric_aggregation_type = "Maximum"
    step_adjustment {
      metric_interval_lower_bound = 0
      scaling_adjustment          = 1
    }

  }
}
resource "aws_appautoscaling_policy" "worker_down" {
  count              = var.deploy_apps ? 1 : 0
  name               = "${var.name}-worker-down"
  policy_type        = "StepScaling"
  resource_id        = aws_appautoscaling_target.worker[0].resource_id
  scalable_dimension = aws_appautoscaling_target.worker[0].scalable_dimension
  service_namespace  = "ecs"
  step_scaling_policy_configuration {
    adjustment_type         = "ChangeInCapacity"
    cooldown                = 300
    metric_aggregation_type = "Maximum"
    step_adjustment {
      metric_interval_upper_bound = 0
      scaling_adjustment          = -1
    }

  }
}
resource "aws_cloudwatch_metric_alarm" "backlog" {
  count       = var.deploy_apps ? 1 : 0
  alarm_name  = "${var.name}-backlog"
  namespace   = "AWS/SQS"
  metric_name = "ApproximateNumberOfMessagesVisible"
  dimensions = { QueueName = aws_sqs_queue.jobs.name
  }
  statistic           = "Average"
  period              = 60
  evaluation_periods  = 2
  threshold           = 64
  comparison_operator = "GreaterThanThreshold"
  treat_missing_data  = "notBreaching"
  alarm_actions       = [aws_appautoscaling_policy.worker_up[0].arn]
}
resource "aws_cloudwatch_metric_alarm" "age" {
  count       = var.deploy_apps ? 1 : 0
  alarm_name  = "${var.name}-oldest-job"
  namespace   = "AWS/SQS"
  metric_name = "ApproximateAgeOfOldestMessage"
  dimensions = { QueueName = aws_sqs_queue.jobs.name
  }
  statistic           = "Maximum"
  period              = 60
  evaluation_periods  = 2
  threshold           = 60
  comparison_operator = "GreaterThanThreshold"
  treat_missing_data  = "notBreaching"
  alarm_actions       = concat([aws_appautoscaling_policy.worker_up[0].arn], var.alarm_topic_arn == "" ? [] : [var.alarm_topic_arn])
}
resource "aws_cloudwatch_metric_alarm" "empty" {
  count               = var.deploy_apps ? 1 : 0
  alarm_name          = "${var.name}-queue-empty"
  comparison_operator = "LessThanOrEqualToThreshold"
  evaluation_periods  = 5
  threshold           = 0
  treat_missing_data  = "notBreaching"
  alarm_actions       = [aws_appautoscaling_policy.worker_down[0].arn]
  metric_query {
    id          = "total"
    expression  = "visible + inflight"
    return_data = true
  }
  metric_query {
    id = "visible"
    metric {
      namespace   = "AWS/SQS"
      metric_name = "ApproximateNumberOfMessagesVisible"
      dimensions = { QueueName = aws_sqs_queue.jobs.name
      }
      period = 60
      stat   = "Maximum"

    }

  }
  metric_query {
    id = "inflight"
    metric {
      namespace   = "AWS/SQS"
      metric_name = "ApproximateNumberOfMessagesNotVisible"
      dimensions = { QueueName = aws_sqs_queue.jobs.name
      }
      period = 60
      stat   = "Maximum"

    }

  }
}
resource "aws_cloudwatch_metric_alarm" "dlq" {
  alarm_name  = "${var.name}-dlq"
  namespace   = "AWS/SQS"
  metric_name = "ApproximateNumberOfMessagesVisible"
  dimensions = { QueueName = aws_sqs_queue.dlq.name
  }
  statistic           = "Maximum"
  period              = 60
  evaluation_periods  = 1
  threshold           = 0
  comparison_operator = "GreaterThanThreshold"
  treat_missing_data  = "notBreaching"
  alarm_actions       = var.alarm_topic_arn == "" ? [] : [var.alarm_topic_arn]
}
resource "aws_cloudwatch_dashboard" "lab" {
  dashboard_name = var.name
  dashboard_body = jsonencode({ widgets = [
    { type = "metric", x = 0, y = 0, width = 12, height = 6, properties = {
      title   = "Fila: visíveis / em andamento", region = var.aws_region, period = 60, stat = "Maximum",
      metrics = [["AWS/SQS", "ApproximateNumberOfMessagesVisible", "QueueName", aws_sqs_queue.jobs.name], ["AWS/SQS", "ApproximateNumberOfMessagesNotVisible", "QueueName", aws_sqs_queue.jobs.name]]
    } },
    { type = "metric", x = 12, y = 0, width = 12, height = 6, properties = {
      title   = "Idade da fila / DLQ", region = var.aws_region, period = 60, stat = "Maximum",
      metrics = [["AWS/SQS", "ApproximateAgeOfOldestMessage", "QueueName", aws_sqs_queue.jobs.name], ["AWS/SQS", "ApproximateNumberOfMessagesVisible", "QueueName", aws_sqs_queue.dlq.name, { yAxis = "right" }]]
    } },
    { type = "metric", x = 0, y = 6, width = 24, height = 6, properties = {
      title   = "Saúde ECS (não é taxa de negócio)", region = var.aws_region, period = 60, stat = "Average",
      metrics = [["AWS/ECS", "CPUUtilization", "ClusterName", aws_ecs_cluster.lab.name, "ServiceName", "service-a"], ["AWS/ECS", "CPUUtilization", "ClusterName", aws_ecs_cluster.lab.name, "ServiceName", "worker"], ["AWS/ECS", "MemoryUtilization", "ClusterName", aws_ecs_cluster.lab.name, "ServiceName", "service-b"]]
      }
    }
  ] })
}

resource "aws_sqs_queue" "dlq" {
  name                      = "${var.name}-dlq"
  message_retention_seconds = 1209600
  sqs_managed_sse_enabled   = true
}
resource "aws_sqs_queue" "jobs" {
  name                       = "${var.name}-jobs"
  message_retention_seconds  = 345600
  receive_wait_time_seconds  = 20
  visibility_timeout_seconds = 45
  sqs_managed_sse_enabled    = true
  # Recebimentos sem token não são falhas. O worker encaminha falhas terminais
  # pela outbox; não configure redrive_policy com maxReceiveCount nesta fila.
}
resource "aws_sqs_queue_policy" "tls" {
  for_each = { jobs = aws_sqs_queue.jobs, dlq = aws_sqs_queue.dlq
  }
  queue_url = each.value.url
  policy = jsonencode({ Version = "2012-10-17", Statement = [{
    Effect = "Deny", Principal = "*", Action = "sqs:*", Resource = each.value.arn,
    Condition = { Bool = { "aws:SecureTransport" = "false" }
    }
  }] })
}
resource "random_password" "redis" {
  length  = 40
  special = false
}
resource "aws_elasticache_subnet_group" "redis" {
  name       = "${var.name}-redis"
  subnet_ids = aws_subnet.private[*].id
}
resource "aws_elasticache_parameter_group" "redis" {
  name   = "${var.name}-redis7"
  family = "redis7"
  parameter {
    name  = "maxmemory-policy"
    value = "noeviction"
  }
}
resource "aws_elasticache_replication_group" "redis" {
  replication_group_id       = "${var.name}-redis"
  description                = "Estado compartilhado do limitador BurstLab"
  engine                     = "redis"
  engine_version             = "7.1"
  node_type                  = "cache.t4g.small"
  num_cache_clusters         = 2
  automatic_failover_enabled = true
  multi_az_enabled           = true
  port                       = 6379
  parameter_group_name       = aws_elasticache_parameter_group.redis.name
  subnet_group_name          = aws_elasticache_subnet_group.redis.name
  security_group_ids         = [aws_security_group.redis.id]
  at_rest_encryption_enabled = true
  transit_encryption_enabled = true
  transit_encryption_mode    = "required"
  auth_token                 = random_password.redis.result
  auth_token_update_strategy = "SET"
  snapshot_retention_limit   = 1
  auto_minor_version_upgrade = true
  apply_immediately          = false
}
resource "aws_db_subnet_group" "db" {
  name       = "${var.name}-db"
  subnet_ids = aws_subnet.private[*].id
}
resource "aws_db_parameter_group" "db" {
  name_prefix = "${var.name}-pg16-"
  family      = "postgres16"
  parameter {
    name  = "rds.force_ssl"
    value = "1"
  }
}
resource "aws_db_instance" "db" {
  identifier                      = "${var.name}-db"
  engine                          = "postgres"
  engine_version                  = "16"
  instance_class                  = "db.t4g.small"
  allocated_storage               = 20
  max_allocated_storage           = 100
  storage_type                    = "gp3"
  storage_encrypted               = true
  db_name                         = "burstlab"
  username                        = "burstlab"
  manage_master_user_password     = true
  db_subnet_group_name            = aws_db_subnet_group.db.name
  parameter_group_name            = aws_db_parameter_group.db.name
  vpc_security_group_ids          = [aws_security_group.db.id]
  publicly_accessible             = false
  multi_az                        = var.rds_multi_az
  backup_retention_period         = 7
  auto_minor_version_upgrade      = true
  deletion_protection             = var.deletion_protection
  skip_final_snapshot             = false
  final_snapshot_identifier       = var.final_snapshot_identifier
  copy_tags_to_snapshot           = true
  enabled_cloudwatch_logs_exports = ["postgresql"]
}
resource "aws_secretsmanager_secret" "redis" {
  name_prefix             = "${var.name}-redis-uri-"
  recovery_window_in_days = 7
}
resource "aws_secretsmanager_secret_version" "redis" {
  secret_id     = aws_secretsmanager_secret.redis.id
  secret_string = "rediss://default:${random_password.redis.result}@${aws_elasticache_replication_group.redis.primary_endpoint_address}:6379"
}

resource "aws_ecs_cluster" "lab" {
  name = var.name
  setting {
    name  = "containerInsights"
    value = "enabled"
  }
}
resource "aws_cloudwatch_log_group" "app" {
  for_each          = local.services
  name              = "/burstlab/${var.name}/${each.key}"
  retention_in_days = 14
}
resource "aws_cloudwatch_log_group" "metrics" {
  name              = "/burstlab/${var.name}/metrics"
  retention_in_days = 14
}
resource "aws_ecs_task_definition" "app" {
  for_each                 = local.apps
  family                   = "${var.name}-${each.key}"
  network_mode             = "awsvpc"
  requires_compatibilities = ["FARGATE"]
  cpu                      = "512"
  memory                   = "1024"
  execution_role_arn       = aws_iam_role.execution[each.key].arn
  task_role_arn            = aws_iam_role.task[each.key].arn
  runtime_platform {
    operating_system_family = "LINUX"
    cpu_architecture        = "X86_64"
  }
  container_definitions = jsonencode([
    {
      name         = each.key, image = "${aws_ecr_repository.app[each.key].repository_url}:${var.image_tag}", essential = true,
      cpu          = 384, memoryReservation = 640, stopTimeout = 120,
      portMappings = [{ containerPort = each.value, protocol = "tcp" }],
      environment = [for k, v in merge({
        PORT                        = tostring(each.value), ROLE = each.key == "worker" ? "worker" : "a",
        AWS_REGION                  = var.aws_region,
        JDBC_URL                    = "jdbc:postgresql://${aws_db_instance.db.address}:5432/burstlab?sslmode=verify-full&sslrootcert=/app/rds-global-bundle.pem",
        JDBC_USERNAME               = "burstlab", SERVICE_B_URL = "http://service-b.${var.name}.local:8081",
        SQS_QUEUE_URL               = aws_sqs_queue.jobs.url, SQS_DLQ_URL = aws_sqs_queue.dlq.url,
        LIMITER_CAPACITY            = "8", LIMITER_RATE = "32", LIMITER_CONCURRENCY = "8", LIMITER_LEASE_MS = "5000",
        ENABLE_UNPROTECTED          = "false", ENABLE_DEMO_ADMIN = "false",
        B_LATENCY_MS                = "200", B_CAPACITY = "8", B_FAIL_EVERY = "0", WORKER_CONCURRENCY = "4",
        JAVA_TOOL_OPTIONS           = "-XX:MaxRAMPercentage=65 -javaagent:/app/opentelemetry-javaagent.jar",
        OTEL_SERVICE_NAME           = each.key, OTEL_RESOURCE_ATTRIBUTES = "deployment.environment.name=aws-lab,service.namespace=burstlab",
        OTEL_EXPORTER_OTLP_ENDPOINT = "http://127.0.0.1:4317", OTEL_EXPORTER_OTLP_PROTOCOL = "grpc",
        OTEL_TRACES_EXPORTER        = "otlp", OTEL_METRICS_EXPORTER = "none", OTEL_LOGS_EXPORTER = "none",
        OTEL_TRACES_SAMPLER         = "parentbased_traceidratio", OTEL_TRACES_SAMPLER_ARG = "0.1"
      }, {}) : { name = k, value = v }],
      secrets          = concat([{ name = "JDBC_PASSWORD", valueFrom = "${aws_db_instance.db.master_user_secret[0].secret_arn}:password::" }], each.key == "service-b" ? [] : [{ name = "REDIS_URI", valueFrom = aws_secretsmanager_secret.redis.arn }]),
      logConfiguration = { logDriver = "awslogs", options = { awslogs-group = aws_cloudwatch_log_group.app[each.key].name, awslogs-region = var.aws_region, awslogs-stream-prefix = "app" } },
      dependsOn        = [{ containerName = "otel", condition = "START" }],
      healthCheck = { command = ["CMD-SHELL", "curl -fsS http://localhost:${each.value}/actuator/health > /dev/null || exit 1"], interval = 30, timeout = 5, retries = 3, startPeriod = 90
      }
    },
    {
      name        = "otel", image = var.otel_collector_image, essential = false,
      cpu         = 128, memoryReservation = 128,
      environment = [{ name = "AOT_CONFIG_CONTENT", value = templatefile("${path.module}/otel-config.yaml.tftpl", { region = var.aws_region, port = each.value, service = each.key, metrics_log_group = aws_cloudwatch_log_group.metrics.name }) }],
      logConfiguration = { logDriver = "awslogs", options = { awslogs-group = aws_cloudwatch_log_group.app[each.key].name, awslogs-region = var.aws_region, awslogs-stream-prefix = "otel" }
      }

    }
  ])
}
resource "aws_ecs_service" "app" {
  for_each                           = local.apps
  name                               = each.key
  cluster                            = aws_ecs_cluster.lab.id
  task_definition                    = aws_ecs_task_definition.app[each.key].arn
  desired_count                      = each.key == "service-b" ? 1 : 2
  launch_type                        = "FARGATE"
  platform_version                   = "1.4.0"
  deployment_minimum_healthy_percent = each.key == "service-b" ? 0 : 100
  deployment_maximum_percent         = each.key == "service-b" ? 100 : 200
  health_check_grace_period_seconds  = each.key == "service-a" ? 120 : null
  enable_execute_command             = false
  deployment_circuit_breaker {
    enable   = true
    rollback = true
  }
  network_configuration {
    subnets          = aws_subnet.private[*].id
    security_groups  = [aws_security_group.app[each.key].id]
    assign_public_ip = false

  }
  dynamic "load_balancer" {
    for_each = each.key == "service-a" ? [1] : []
    content {
      target_group_arn = aws_lb_target_group.a.arn
      container_name   = each.key
      container_port   = each.value
    }

  }
  dynamic "service_registries" {
    for_each = each.key == "service-b" ? [1] : []
    content {
      registry_arn = aws_service_discovery_service.b.arn
    }

  }
  lifecycle {
    ignore_changes = [desired_count]
  }
  depends_on = [aws_lb_listener_rule.api, aws_iam_role_policy.execution, aws_iam_role_policy.telemetry, aws_iam_role_policy.queue_a, aws_iam_role_policy.queue_worker, aws_secretsmanager_secret_version.redis]
}

data "aws_iam_policy_document" "ecs_assume" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["ecs-tasks.amazonaws.com"]
    }
    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values   = ["arn:${data.aws_partition.current.partition}:ecs:${var.aws_region}:${data.aws_caller_identity.current.account_id}:*"]
    }

  }
}
resource "aws_iam_role" "execution" {
  for_each           = local.services
  name               = "${var.name}-${each.key}-execution"
  assume_role_policy = data.aws_iam_policy_document.ecs_assume.json
}
resource "aws_iam_role_policy" "execution" {
  for_each = local.services
  role     = aws_iam_role.execution[each.key].id
  policy = jsonencode({ Version = "2012-10-17", Statement = [
    { Effect = "Allow", Action = ["ecr:GetAuthorizationToken"], Resource = "*" },
    { Effect = "Allow", Action = ["ecr:BatchCheckLayerAvailability", "ecr:GetDownloadUrlForLayer", "ecr:BatchGetImage"], Resource = aws_ecr_repository.app[each.key].arn },
    { Effect = "Allow", Action = ["logs:CreateLogStream", "logs:PutLogEvents"], Resource = "${aws_cloudwatch_log_group.app[each.key].arn}:*" },
    { Effect = "Allow", Action = ["secretsmanager:GetSecretValue"], Resource = concat([aws_db_instance.db.master_user_secret[0].secret_arn], each.key == "service-b" ? [] : [aws_secretsmanager_secret.redis.arn])
    }
  ] })
}
resource "aws_iam_role" "task" {
  for_each           = local.services
  name               = "${var.name}-${each.key}-task"
  assume_role_policy = data.aws_iam_policy_document.ecs_assume.json
}
resource "aws_iam_role_policy" "telemetry" {
  for_each = local.services
  role     = aws_iam_role.task[each.key].id
  policy = jsonencode({ Version = "2012-10-17", Statement = [
    { Effect = "Allow", Action = ["xray:PutTraceSegments", "xray:PutTelemetryRecords"], Resource = "*" },
    { Effect = "Allow", Action = ["logs:CreateLogStream", "logs:PutLogEvents", "logs:DescribeLogStreams"], Resource = "${aws_cloudwatch_log_group.metrics.arn}:*"
    }
  ] })
}
resource "aws_iam_role_policy" "queue_a" {
  role = aws_iam_role.task["service-a"].id
  policy = jsonencode({ Version = "2012-10-17", Statement = [{
    Effect = "Allow", Action = ["sqs:SendMessage"], Resource = [aws_sqs_queue.jobs.arn, aws_sqs_queue.dlq.arn]
  }] })
}
resource "aws_iam_role_policy" "queue_worker" {
  role = aws_iam_role.task["worker"].id
  policy = jsonencode({ Version = "2012-10-17", Statement = [
    { Effect = "Allow", Action = ["sqs:ReceiveMessage", "sqs:DeleteMessage", "sqs:ChangeMessageVisibility", "sqs:GetQueueAttributes", "sqs:SendMessage"], Resource = aws_sqs_queue.jobs.arn },
    { Effect = "Allow", Action = ["sqs:SendMessage"], Resource = aws_sqs_queue.dlq.arn
    }
  ] })
}

resource "aws_ecr_repository" "app" {
  for_each             = local.services
  name                 = "${var.name}/${each.key}"
  image_tag_mutability = "IMMUTABLE"
  image_scanning_configuration {
    scan_on_push = true
  }
  encryption_configuration {
    encryption_type = "AES256"
  }
  force_delete = false
}
resource "aws_ecr_lifecycle_policy" "app" {
  for_each   = aws_ecr_repository.app
  repository = each.value.name
  policy = jsonencode({ rules = [{ rulePriority = 1, description = "Remover imagens sem tag antigas", selection = {
    tagStatus = "untagged", countType = "sinceImagePushed", countUnit = "days", countNumber = 7
  }, action = { type = "expire" } }] })
}

resource "aws_lb" "api" {
  name                       = "${var.name}-api"
  internal                   = false
  load_balancer_type         = "application"
  security_groups            = [aws_security_group.alb.id]
  subnets                    = aws_subnet.public[*].id
  drop_invalid_header_fields = true
  enable_deletion_protection = var.deletion_protection
}
resource "aws_lb_target_group" "a" {
  name                 = "${var.name}-a"
  port                 = 8080
  protocol             = "HTTP"
  target_type          = "ip"
  vpc_id               = aws_vpc.lab.id
  deregistration_delay = 30
  health_check {
    path     = "/actuator/health"
    matcher  = "200"
    interval = 30
  }
}
resource "aws_lb_listener" "https" {
  load_balancer_arn = aws_lb.api.arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = var.certificate_arn
  default_action {
    type = "fixed-response"
    fixed_response {
      content_type = "text/plain"
      message_body = "Rota não publicada"
      status_code  = "404"
    }

  }
}
resource "aws_lb_listener_rule" "api" {
  listener_arn = aws_lb_listener.https.arn
  priority     = 10
  action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.a.arn
  }
  condition {
    path_pattern {
      values = ["/api/*"]
    }
  }
}
resource "aws_route53_record" "api" {
  zone_id = var.route53_zone_id
  name    = var.dns_name
  type    = "A"
  alias {
    name                   = aws_lb.api.dns_name
    zone_id                = aws_lb.api.zone_id
    evaluate_target_health = true

  }
}

# Tarefa operacional inativa. Só é executada pelo operador para um UUID revisado.
resource "aws_ecs_task_definition" "maintenance" {
  family                   = "${var.name}-maintenance"
  network_mode             = "awsvpc"
  requires_compatibilities = ["FARGATE"]
  cpu                      = "256"
  memory                   = "512"
  execution_role_arn       = aws_iam_role.execution["service-a"].arn
  runtime_platform {
    operating_system_family = "LINUX"
    cpu_architecture        = "X86_64"
  }
  container_definitions = jsonencode([{
    name       = "maintenance"
    image      = "public.ecr.aws/docker/library/postgres:16-alpine"
    essential  = true
    entryPoint = ["/bin/sh", "-c"]
    command    = ["set -eu; wget -q https://truststore.pki.rds.amazonaws.com/global/global-bundle.pem -O /tmp/rds.pem; exec psql -v ON_ERROR_STOP=1 -c \"$REPLAY_SQL\""]
    environment = [
      { name = "PGHOST", value = aws_db_instance.db.address },
      { name = "PGDATABASE", value = "burstlab" },
      { name = "PGUSER", value = "burstlab" },
      { name = "PGSSLMODE", value = "verify-full" },
      { name = "PGSSLROOTCERT", value = "/tmp/rds.pem" },
      { name = "REPLAY_SQL", value = "SELECT 1;" }
    ]
    secrets = [{ name = "PGPASSWORD", valueFrom = "${aws_db_instance.db.master_user_secret[0].secret_arn}:password::" }]
    logConfiguration = {
      logDriver = "awslogs"
      options = {
        awslogs-group         = aws_cloudwatch_log_group.app["service-a"].name
        awslogs-region        = var.aws_region
        awslogs-stream-prefix = "maintenance"
      }
    }
  }])
}
output "maintenance_task_definition" { value = aws_ecs_task_definition.maintenance.arn }
output "maintenance_network" {
  value = {
    awsvpcConfiguration = {
      subnets        = aws_subnet.private[*].id
      securityGroups = [aws_security_group.app["service-a"].id]
      assignPublicIp = "DISABLED"
    }
  }
}

resource "aws_vpc" "lab" {
  cidr_block           = "10.42.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = { Name = var.name
  }
}
resource "aws_subnet" "public" {
  count                   = 2
  vpc_id                  = aws_vpc.lab.id
  cidr_block              = cidrsubnet(aws_vpc.lab.cidr_block, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false
  tags = { Name = "${var.name}-public-${count.index}"
  }
}
resource "aws_subnet" "private" {
  count             = 2
  vpc_id            = aws_vpc.lab.id
  cidr_block        = cidrsubnet(aws_vpc.lab.cidr_block, 8, count.index + 10)
  availability_zone = data.aws_availability_zones.available.names[count.index]
  tags = { Name = "${var.name}-private-${count.index}"
  }
}
resource "aws_internet_gateway" "lab" {
  vpc_id = aws_vpc.lab.id
}
resource "aws_eip" "nat" {
  domain = "vpc"
}
resource "aws_nat_gateway" "lab" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id
  depends_on    = [aws_internet_gateway.lab]
}
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.lab.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.lab.id
  }
}
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.lab.id
  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.lab.id
  }
}
resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}
resource "aws_route_table_association" "private" {
  count          = 2
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}
resource "aws_security_group" "alb" {
  name_prefix = "${var.name}-alb-"
  vpc_id      = aws_vpc.lab.id
}
resource "aws_security_group" "app" {
  for_each    = local.services
  name_prefix = "${var.name}-${each.key}-"
  vpc_id      = aws_vpc.lab.id
}
resource "aws_security_group" "redis" {
  name_prefix = "${var.name}-redis-"
  vpc_id      = aws_vpc.lab.id
}
resource "aws_security_group" "db" {
  name_prefix = "${var.name}-db-"
  vpc_id      = aws_vpc.lab.id
}
resource "aws_vpc_security_group_ingress_rule" "https" {
  security_group_id = aws_security_group.alb.id
  cidr_ipv4         = var.allowed_ingress_cidr
  from_port         = 443
  to_port           = 443
  ip_protocol       = "tcp"
}
resource "aws_vpc_security_group_egress_rule" "alb_to_a" {
  security_group_id            = aws_security_group.alb.id
  referenced_security_group_id = aws_security_group.app["service-a"].id
  from_port                    = 8080
  to_port                      = 8080
  ip_protocol                  = "tcp"
}
resource "aws_vpc_security_group_ingress_rule" "a_from_alb" {
  security_group_id            = aws_security_group.app["service-a"].id
  referenced_security_group_id = aws_security_group.alb.id
  from_port                    = 8080
  to_port                      = 8080
  ip_protocol                  = "tcp"
}
resource "aws_vpc_security_group_ingress_rule" "b_from_clients" {
  for_each                     = toset(["service-a", "worker"])
  security_group_id            = aws_security_group.app["service-b"].id
  referenced_security_group_id = aws_security_group.app[each.key].id
  from_port                    = 8081
  to_port                      = 8081
  ip_protocol                  = "tcp"
}
resource "aws_vpc_security_group_ingress_rule" "redis_from_clients" {
  for_each                     = toset(["service-a", "worker"])
  security_group_id            = aws_security_group.redis.id
  referenced_security_group_id = aws_security_group.app[each.key].id
  from_port                    = 6379
  to_port                      = 6379
  ip_protocol                  = "tcp"
}
resource "aws_vpc_security_group_ingress_rule" "db_from_apps" {
  for_each                     = local.services
  security_group_id            = aws_security_group.db.id
