#!/usr/bin/env python3
"""Carga open-loop real; biblioteca padrão. Mede admissão HTTP e conclusão dos jobs separadamente."""
import argparse, concurrent.futures as cf, csv, json, pathlib, time, urllib.request, urllib.error, uuid

def request(url,body=None,key=None):
    headers={'Content-Type':'application/json'}
    if key: headers['Idempotency-Key']=key
    data=None if body is None else json.dumps(body).encode()
    try:
        with urllib.request.urlopen(urllib.request.Request(url,data=data,headers=headers),timeout=3) as r:return r.status,json.load(r)
    except urllib.error.HTTPError as e:
        try: payload=json.load(e)
        except Exception: payload={'error':str(e)}
        return e.code,payload
    except Exception as e:return 0,{'error':str(e)}

def run(args,mode):
    path={'raw':'unprotected','sync':'sync','async':'jobs'}[mode];rows=[];futures=[]
    start=time.monotonic();duration=args.warmup+args.burst_duration+args.after
    def one(index,scheduled):
        sent=time.monotonic();code,body=request(args.url+'/api/'+path,{'value':'load-'+str(index)},str(uuid.uuid4()))
        return {'n':index,'scheduled_s':scheduled,'send_lag_ms':round((sent-start-scheduled)*1000,2),'latency_ms':round((time.monotonic()-sent)*1000,2),'status':code,'jobId':body.get('jobId','')}
    with cf.ThreadPoolExecutor(max_workers=256) as pool:
        at=0.;i=0
        while at<duration:
            time.sleep(max(0,start+at-time.monotonic()));futures.append(pool.submit(one,i,at));i+=1
            rate=args.burst if args.warmup<=at<args.warmup+args.burst_duration else args.normal
            at+=1/rate
        rows=[f.result() for f in futures]
    accepted=[r['jobId'] for r in rows if r['status']==202];terminal={};until=time.monotonic()+130
    while accepted and time.monotonic()<until:
        with cf.ThreadPoolExecutor(max_workers=16) as pool:
            states=list(pool.map(lambda job:(job,request(args.url+'/api/jobs/'+job)),accepted))
        pending=[]
        for job,(code,state) in states:
            if state.get('status') in ('SUCCEEDED','FAILED','EXPIRED','RESULT_UNKNOWN'):terminal[job]=state
            else:pending.append(job)
        accepted=pending
        if accepted:time.sleep(2)
    counts={str(c):sum(r['status']==c for r in rows) for c in sorted(set(r['status'] for r in rows))}
    lat=sorted(r['latency_ms'] for r in rows);report={'mode':mode,'offered':len(rows),'http':counts,'p50_ms':lat[len(lat)//2],'p95_ms':lat[int(len(lat)*.95)],'max_send_lag_ms':max(r['send_lag_ms'] for r in rows),'job_states':{s:sum(j['status']==s for j in terminal.values()) for s in ('SUCCEEDED','FAILED','EXPIRED','RESULT_UNKNOWN')},'jobs_pending_after_130s':len(accepted),'elapsed_s':round(time.monotonic()-start,2),'assumptions':vars(args)}
    out=pathlib.Path(args.output);out.mkdir(exist_ok=True,parents=True)
    with (out/(mode+'.csv')).open('w') as f:w=csv.DictWriter(f,fieldnames=rows[0].keys());w.writeheader();w.writerows(rows)
    (out/(mode+'.json')).write_text(json.dumps(report,indent=2));print(json.dumps(report,indent=2))

if __name__=='__main__':
    p=argparse.ArgumentParser(description=__doc__);p.add_argument('--mode',choices=['all','raw','sync','async'],default='all');p.add_argument('--url',default='http://localhost:8080');p.add_argument('--normal',type=int,default=20);p.add_argument('--burst',type=int,default=120);p.add_argument('--burst-duration',type=int,default=10);p.add_argument('--warmup',type=int,default=5);p.add_argument('--after',type=int,default=10);p.add_argument('--output',default='results');a=p.parse_args()
    if min(a.normal,a.burst,a.burst_duration,a.warmup,a.after)<1:p.error('valores devem ser positivos')
    for mode in ['raw','sync','async'] if a.mode=='all' else [a.mode]:run(a,mode);time.sleep(5)

#!/usr/bin/env python3
"""Reprocessamento local deliberado de UM job após corrigir causa; mantém idempotência B."""
import argparse, subprocess, uuid
p=argparse.ArgumentParser(description=__doc__);p.add_argument('job_id',type=uuid.UUID);a=p.parse_args()
# Publication resets atomically with job state. DLQ copy remains as audit, harmless until manually deleted.
query="""BEGIN;
CREATE TABLE IF NOT EXISTS redrive_audit (snapshot JSONB NOT NULL, recorded_at TIMESTAMPTZ NOT NULL DEFAULT now());
INSERT INTO redrive_audit(snapshot) SELECT to_jsonb(jobs) FROM jobs WHERE id='%s' AND status IN ('FAILED','EXPIRED','RESULT_UNKNOWN');
DELETE FROM outbox WHERE job_id='%s' AND destination='DLQ';
UPDATE jobs SET status='QUEUED',attempts=0,owner=NULL,locked_until=NULL,next_attempt=now(),deadline=now()+interval '120 seconds',error=NULL WHERE id='%s' AND status IN ('FAILED','EXPIRED','RESULT_UNKNOWN');
UPDATE outbox SET published_at=NULL WHERE job_id='%s' AND destination='MAIN' AND EXISTS(SELECT 1 FROM jobs WHERE id='%s' AND status='QUEUED');
COMMIT;"""%(a.job_id,a.job_id,a.job_id,a.job_id,a.job_id)
subprocess.run(['docker','compose','exec','-T','postgres','psql','-v','ON_ERROR_STOP=1','-U','burstlab','-d','burstlab','-c',query],check=True)
print('Job reenfileirado se estava FAILED/EXPIRED. Preserve relatório anterior para auditoria; tentativa foi reiniciada. Cópia DLQ preservada.')

package br.com.burstlab.a;
import br.com.burstlab.common.*;
import jakarta.servlet.http.HttpServletRequest;
import org.springframework.http.*;
import org.springframework.web.bind.annotation.*;
import io.micrometer.core.instrument.MeterRegistry;
import java.util.*;
@RestController @RequestMapping("/api")
public class ApiController {
 private final RedisLimiter limiter;private final BClient b;private final JobStore jobs;private final MeterRegistry metrics;
 public ApiController(RedisLimiter limiter,BClient b,JobStore jobs,MeterRegistry metrics){this.limiter=limiter;this.b=b;this.jobs=jobs;this.metrics=metrics;}
 @PostMapping("/sync")
 public ResponseEntity<?> sync(@RequestHeader("Idempotency-Key") String key,@RequestBody Payload payload,HttpServletRequest req)throws InterruptedException {
  Payload.key(key);long deadline=System.currentTimeMillis()+2000;long waitUntil=System.nanoTime()+50_000_000;RedisLimiter.Admission a;
  try{
   while(true){a=limiter.acquire();if(a.allowed())break;
    if(System.nanoTime()>=waitUntil||a.retryAfterMs()>50||System.currentTimeMillis()+250>deadline){metrics.counter("burstlab_admission","result","denied").increment();return ResponseEntity.status(429).header("Retry-After",""+Math.max(1,(a.retryAfterMs()+999)/1000)).body(Map.of("error","capacidade global indisponível","retryAfterMs",a.retryAfterMs(),"reason",a.reason()));}
    Thread.sleep(Math.max(1,Math.min(10,a.retryAfterMs())));
   }
  }catch(io.lettuce.core.RedisException e){metrics.counter("burstlab_admission","result","redis_unavailable").increment();return ResponseEntity.status(503).header("Retry-After","1").body(Map.of("error","Redis indisponível; política fail-closed"));}
  metrics.counter("burstlab_admission","result","allowed").increment();
  BClient.Result result=b.call("sync:"+key,payload.value(),req.getAttribute("correlationId").toString(),deadline);
  if(result.certain()){try{limiter.release(a);}catch(Exception ignored){/* lease expira; token nunca é devolvido */}}
  return ResponseEntity.status(result.status()).contentType(MediaType.APPLICATION_JSON).body(result.body());
 }
 @PostMapping("/unprotected")
 public ResponseEntity<?> unprotected(@RequestHeader("Idempotency-Key") String key,@RequestBody Payload payload,HttpServletRequest req){
  if(!Settings.flag("ENABLE_UNPROTECTED"))return ResponseEntity.status(404).build();
  BClient.Result r=b.call("raw:"+Payload.key(key),payload.value(),req.getAttribute("correlationId").toString(),System.currentTimeMillis()+2000);
  return ResponseEntity.status(r.status()).contentType(MediaType.APPLICATION_JSON).body(r.body());
 }
 @PostMapping("/jobs")
 public ResponseEntity<?> async(@RequestHeader("Idempotency-Key") String key,@RequestBody Payload payload,HttpServletRequest req){
  JobStore.Job job=jobs.accept(Payload.key(key),payload.value(),req.getAttribute("correlationId").toString());
  return ResponseEntity.accepted().header("Location","/api/jobs/"+job.id()).body(Map.of("jobId",job.id(),"status",job.status(),"statusUrl","/api/jobs/"+job.id()));
 }
 @GetMapping("/jobs/{id}") public JobStore.Job status(@PathVariable UUID id){return jobs.get(id);}
}

package br.com.burstlab.a;
import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.scheduling.annotation.EnableScheduling;
@SpringBootApplication(scanBasePackages="br.com.burstlab") @EnableScheduling
public class ServiceA { public static void main(String[] args) { SpringApplication.run(ServiceA.class,args); } }

package br.com.burstlab.b;
import br.com.burstlab.common.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.http.*;
import org.springframework.web.bind.annotation.*;
import io.micrometer.core.instrument.MeterRegistry;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
@RestController
public class DemoController {
 private final JdbcTemplate db;private final TransactionTemplate tx;private final MeterRegistry metrics;
 private final AtomicInteger calls=new AtomicInteger(),active=new AtomicInteger();
 private volatile int latency=Settings.integer("B_LATENCY_MS",200),capacity=Settings.integer("B_CAPACITY",8),failEvery=Settings.integer("B_FAIL_EVERY",0);
 public DemoController(JdbcTemplate db,TransactionTemplate tx,MeterRegistry metrics){this.db=db;this.tx=tx;this.metrics=metrics;metrics.gauge("burstlab_b_active_local",active);}
 @PostMapping("/api/work")
 public ResponseEntity<?> work(@RequestHeader("Idempotency-Key")String key,@RequestHeader("X-Deadline-Epoch-Ms")long deadline,@RequestBody Payload p){
  Payload.operationKey(key);return tx.execute(status->{
   // Lock is held by PostgreSQL until commit/rollback, not by a client-side lease.
   Boolean own=db.queryForObject("SELECT pg_try_advisory_xact_lock(hashtextextended(?,0))",Boolean.class,key);
   if(!Boolean.TRUE.equals(own))return error(503,"operação idêntica em andamento");
   var existing=db.queryForList("SELECT payload,result FROM b_effects WHERE operation_id=?",key);
   if(!existing.isEmpty()){var row=existing.get(0);if(!row.get("payload").equals(p.value()))return error(409,"mesma chave com payload diferente");metrics.counter("burstlab_b_deduplicated").increment();return ResponseEntity.ok(Map.of("result",row.get("result"),"duplicate",true));}
   boolean acquired=false;for(int slot=0;slot<capacity;slot++){if(Boolean.TRUE.equals(db.queryForObject("SELECT pg_try_advisory_xact_lock(4288,?)",Boolean.class,slot))){acquired=true;break;}}
   if(!acquired){metrics.counter("burstlab_b_rejected").increment();return error(503,"B no limite global");}
   if(deadline<System.currentTimeMillis()+latency)return error(504,"prazo insuficiente em B");
   active.incrementAndGet();try{
    Thread.sleep(latency);
    if(deadline<System.currentTimeMillis())return error(504,"prazo expirou antes do efeito");
    if(failEvery>0&&calls.incrementAndGet()%failEvery==0)return error(503,"falha de demonstração");
    String result="processado:"+p.value();
    db.update("INSERT INTO b_effects(operation_id,payload,result) VALUES (?,?,?)",key,p.value(),result);
    metrics.counter("burstlab_b_effects").increment();return ResponseEntity.ok(Map.of("result",result,"duplicate",false));
   }catch(InterruptedException e){Thread.currentThread().interrupt();status.setRollbackOnly();return error(503,"B interrompido");}finally{active.decrementAndGet();}
  });
 }
 @GetMapping("/api/results/{key}") public ResponseEntity<?> result(@PathVariable String key){
  Payload.operationKey(key);var rows=db.queryForList("SELECT result FROM b_effects WHERE operation_id=?",key);
  return rows.isEmpty()?ResponseEntity.notFound().build():ResponseEntity.ok(Map.of("result",rows.get(0).get("result"),"duplicate",true));
 }
 private ResponseEntity<?> error(int code,String reason){return ResponseEntity.status(code).body(Map.of("error",reason));}
 @GetMapping("/demo/config")public Map<String,Integer> config(){return Map.of("latencyMs",latency,"capacity",capacity,"failEvery",failEvery);}
 @PostMapping("/demo/config")public ResponseEntity<?> config(@RequestBody Map<String,Integer> cfg){
  if(!Settings.flag("ENABLE_DEMO_ADMIN"))return ResponseEntity.status(404).build();
  int l=cfg.getOrDefault("latencyMs",latency),f=cfg.getOrDefault("failEvery",failEvery);
  // Capacity is deployment-wide immutable to avoid replica drift. Set B_CAPACITY at startup.
  if(l<1||l>3000||f<0)return error(400,"latência 1–3000ms; failEvery >= 0");latency=l;failEvery=f;return ResponseEntity.ok(config());
 }
}

